/* EnvKit promo v3 — one scene builder for all three cuts (16:9 main, 9:16, 16:9 15 s ad).
 * Every time comes from window.TIMING (generated by tools/edit_v3.py from the measured voiceover):
 * marks are beats on the 140 BPM grid, words/cards carry the VO word onsets used by the captions.
 * Every UI surface is a real EnvKit screenshot in a .panel (camera clamped by PromoLib.camTo);
 * every word on screen is HTML. The hook "nods" (dialog, locked chips, RAM meter) are generic,
 * brand-free HTML, blurred so they read as mood. Deterministic: no Date/Math.random. */
(function () {
  const T = window.TIMING;
  const ROOT = document.getElementById('root');
  // data-full-duration: a hook-only render (tools/compose_v3.py --hook) keeps the full timeline maths
  const W = +ROOT.dataset.width, H = +ROOT.dataset.height, LEN = +(ROOT.dataset.fullDuration || ROOT.dataset.duration);
  const PORTRAIT = H > W;
  const { tl, panel, camTo, ring, sweep, trails, grain, floor } = PromoLib.create({ width: W, height: H, duration: LEN });
  const BEAT = T.beat, M = T.marks;
  const S = (k, off = 0) => +((M[k] + off) * BEAT).toFixed(4);   // mark (+ beats) -> seconds
  const has = (k) => M[k] !== undefined;
  const EXPO = 'expo.out', IO = 'power3.inOut', SINE = 'sine.inOut';
  const $ = (s, r = document) => r.querySelector(s);
  const el = (tag, cls, parent, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html !== undefined) e.innerHTML = html; (parent || WORLD).appendChild(e); return e; };
  const WORLD = $('#world');
  const ft = (t, from, to, at) => tl.fromTo(t, from, { ...to, immediateRender: false }, at);
  const words = (lid) => T.words.filter((w) => w.line === lid).sort((a, b) => a.i - b.i);
  const card = (lid) => T.cards.find((c) => c.line === lid);
  const SHOT = (n) => `assets/${n}.png`;

  // ── Scene windows: each scene runs from its mark to the next scene's mark ───────
  const order = ['h1', 'x3', 'slam', 'stack', 'pickin', 'live', 'https', 'sites', 'svc', 'run', 'ai', 'mont', 'here', 'bd', 'free', 'card', 'end'];
  if (!has('h4e')) { /* 15 s cut: no turn */ }
  const present = order.filter(has);
  const win = (k) => { const i = present.indexOf(k); return [S(k), S(present[i + 1] || 'end')]; };
  function scene(cls, k0, k1, stage = true) {
    const r = el('div', 'scene' + (stage ? ' stage' : '') + (cls ? ' ' + cls : ''));
    const t0 = typeof k0 === 'number' ? k0 : S(k0), t1 = typeof k1 === 'number' ? k1 : S(k1);
    tl.set(r, { autoAlpha: 1 }, Math.max(0, t0 - 0.001));
    tl.set(r, { autoAlpha: 0 }, t1);
    return r;
  }
  function shotPanel(parent, img, crop, geo) {
    const p = el('div', 'panel', parent);
    const c = el('div', 'cnt', p);
    const i = el('img', 'shot', c); i.src = SHOT(img); i.alt = '';
    el('div', 'sheen', p);
    const P = panel(p, { crop, w: geo.w, left: geo.left, top: geo.top, view: geo.view });
    P.c = c;
    return P;
  }
  // panel geometry: centred in the picture area (above the captions on 16:9, upper-middle on 9:16)
  function geo(crop, wMax, hMax, cy) {
    const ar = crop[2] / crop[3];
    let w = Math.min(wMax, hMax * ar);
    const h = w / ar;
    return { w, left: (W - w) / 2, top: (cy !== undefined ? cy : (PORTRAIT ? 760 : 470)) - h / 2 };
  }
  const A = PORTRAIT ? { pw: 1000, ph: 900, big: 150, hero: 128, turn: 86, cap: 84, capY: 1500, free: 215 } :
                       { pw: 1360, ph: 800, big: 170, hero: 150, turn: 78, cap: 54, capY: 1080 - 116, free: 290 };
  const flash = el('div', 'flash'); const flashM = el('div', 'flash mint');
  const black = el('div', 'blackout');
  function doFlash(at, o = 0.85, mint = false) {
    ft(mint ? flashM : flash, { opacity: o }, { opacity: 0, duration: 0.22, ease: 'power2.out' }, at);
  }
  function shake(at, amp = 18, n = 6) {
    for (let i = 0; i < n; i++) {
      const k = (n - i) / n, sx = ((i * 37) % 7 - 3) / 3, sy = ((i * 53) % 5 - 2) / 2;
      tl.to(WORLD, { x: sx * amp * k, y: sy * amp * k * 0.7, duration: 0.033, ease: 'none' }, at + i * 0.033);
    }
    tl.to(WORLD, { x: 0, y: 0, duration: 0.05 }, at + n * 0.033);
  }
  function tokens(parent, toks, cls = 'w') {
    return toks.map((tk, i) => {
      const s = el('span', cls, parent, tk.w.replace(/\.test$/, '<span class="dotm">.test</span>'));
      if (i < toks.length - 1) parent.appendChild(document.createTextNode(' '));
      return s;
    });
  }

  // ── Backdrop ──────────────────────────────────────────────────────────────────
  trails('#trails', { count: PORTRAIT ? 14 : 18 });
  floor('#floor'); grain('#grain');
  gsap.set('#trails', { opacity: 0.5 }); gsap.set('#floor', { opacity: 0 }); gsap.set('#glow', { x: -160, y: -30, scale: 1 });
  tl.to('#glow', { x: 200, y: 30, scale: 1.25, duration: LEN, ease: 'none' }, 0);
  tl.to('#floor', { opacity: 0.9, duration: 1.2, ease: SINE }, S('slam'));
  tl.to('#trails', { opacity: 0.85, duration: 0.2 }, S('slam'));
  tl.to('#trails', { opacity: 0.35, duration: 1.2, ease: SINE }, S('slam', 4));
  const vids = [...document.querySelectorAll('video.vid')];
  vids.forEach((v) => {
    const t0 = +v.dataset.start, t1 = t0 + +v.dataset.duration, peak = +(v.dataset.peak || 0.6);
    gsap.set(v, { opacity: 0 });
    if (v.dataset.ramp) {   // light-speed tunnel: starts as a glimmer in the dark, peaks on the slam, then clears
      const tp = +v.dataset.ramp;
      ft(v, { opacity: 0, scale: 1.0 }, { opacity: 0.16, scale: 1.08, duration: 0.5, ease: 'power1.out' }, t0);
      tl.to(v, { opacity: peak, scale: 1.35, duration: Math.max(0.2, tp - t0 - 0.5), ease: 'power3.in' }, t0 + 0.5);
      tl.to(v, { opacity: 0.35, scale: 1.1, duration: 0.6, ease: 'power2.out' }, tp + 0.05);
      tl.to(v, { opacity: 0, duration: 0.35, ease: 'power1.in' }, t1 - 0.36);
      return;
    }
    ft(v, { opacity: 0, scale: +(v.dataset.zoom || 1.1) }, { opacity: peak, scale: 1, duration: Math.min(0.6, (t1 - t0) / 3), ease: 'power1.out' }, t0);
    tl.to(v, { opacity: 0, duration: 0.35, ease: 'power1.in' }, t1 - 0.36);
  });

  // ── 1. Hook: three pains, each struck through as the next one slams in ─────────
  {
    const R = scene('hook', 0, S('x3'), false);
    const nods = [el('div', 'nod', R), el('div', 'nod', R), el('div', 'nod', R)];
    // nods (generic, brand-free, blurred): 1 error dialogs about port 80, 2 database crash lines, 3 version mismatch
    const dl = [['Error', 'listen tcp 0.0.0.0:80: bind: address already in use'], ['Web server failed to start', 'Port 80 is used by another process.'], ['Error', 'bind() to 0.0.0.0:80 failed (Address already in use)']];
    const dpos = PORTRAIT ? [[60, 330, -4], [400, 560, 3], [120, 1240, -2]] : [[150, 120, -4], [1180, 170, 3], [640, 660, -2]];
    const dlgs = dl.map(([t, b], i) => { const d = el('div', 'dlg err', nods[0], `<b>${t}</b>${b}<div class="row"><span>Quit</span><span class="p">Retry</span></div>`); gsap.set(d, { left: dpos[i][0], top: dpos[i][1], rotation: dpos[i][2] }); return d; });
    const xi = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" fill="none" stroke="#ff8a96" stroke-width="2"/><path d="M8.5 8.5l7 7M15.5 8.5l-7 7" stroke="#ff8a96" stroke-width="2" stroke-linecap="round"/></svg>';
    const cpos = PORTRAIT ? [[70, 420], [300, 620], [90, 1220], [330, 1400]] : [[140, 170], [1080, 230], [200, 770], [1060, 810]];
    const chipsL = ['mysqld exited (code 1)', 'InnoDB: crash recovery', "can't connect to :3306", 'database stopped'].map((n, i) => { const c = el('div', 'lockchip err', nods[1], `${xi}${n}`); gsap.set(c, { left: cpos[i][0], top: cpos[i][1] }); return c; });
    const vpos = PORTRAIT ? [[90, 430], [330, 640], [110, 1230], [300, 1410]] : [[160, 180], [1120, 240], [230, 780], [1000, 820]];
    const verL = ['php -v  7.4.33', 'requires php ^8.3', 'unsupported PHP version', 'switch version?'].map((n, i) => { const c = el('div', 'lockchip amb', nods[2], `${xi}${n}`); gsap.set(c, { left: vpos[i][0], top: vpos[i][1] }); return c; });
    // 9:16: each pain is two rows (each with its own strike); 16:9: one row
    const ROWS = { H1: [3], H2: [3], H3: [2] };
    const lines = ['H1', 'H2', 'H3'].map((lid, k) => {
      const c = card(lid);
      const p = el('div', 'pain', R);
      p.style.fontSize = (PORTRAIT ? 88 : 98) + 'px';
      const cuts = PORTRAIT ? [0, ...ROWS[lid], c.toks.length] : [0, c.toks.length];
      const ws = [], st = [], gr = [], gc = [];
      for (let r = 0; r + 1 < cuts.length; r++) {
        const row = c.toks.slice(cuts[r], cuts[r + 1]);
        const txt = el('span', 'txt', p);
        if (r) p.insertBefore(document.createElement('br'), txt);
        ws.push(...tokens(txt, row));
        const s1 = el('span', 'strike', txt);
        gsap.set(s1, { scaleX: 0, rotation: -2, transformOrigin: '0% 50%' });
        st.push(s1);
        gr.push(el('span', 'ghost r', txt, row.map((t) => t.w).join(' ')));
        gc.push(el('span', 'ghost c', txt, row.map((t) => t.w).join(' ')));
      }
      if (PORTRAIT) p.style.lineHeight = '1.05';
      return { p, ws, st, gr, gc, c };
    });
    const cy = PORTRAIT ? 880 : 470, lh = PORTRAIT ? 230 : 130;
    const xs = [S('x1'), S('x2'), S('x3')];
    lines.forEach((L, k) => {
      const t0 = L.c.t0;
      gsap.set(L.p, { top: cy - (PORTRAIT ? 120 : lh / 2), opacity: 0 });
      tl.set(L.p, { opacity: 1 }, t0 - 0.02);
      L.c.toks.forEach((tk, i) => ft(L.ws[i], { opacity: 0, scale: 1.55, y: -20, filter: 'blur(14px)' }, { opacity: 1, scale: 1, y: 0, filter: 'blur(0px)', duration: 0.16, ease: 'power4.out' }, tk.t));
      shake(t0, k === 2 ? 22 : 16, 5);
      doFlash(t0, 0.18 + 0.06 * k);
      // nod behind the line
      const nd = nods[k];
      ft(nd, { opacity: 0, scale: 1.08 }, { opacity: 0.55, scale: 1, duration: 0.25, ease: 'power2.out' }, t0);
      tl.to(nd, { opacity: 0, duration: 0.12 }, xs[k] - 0.02);
      // strike + glitch on the next beat, then the struck line is pushed up and dimmed
      const x = xs[k];
      L.st.forEach((s1, r) => ft(s1, { scaleX: 0 }, { scaleX: 1, duration: 0.1, ease: 'power3.out' }, x - 0.11 + r * 0.03));
      [[L.gr, -14, 6], [L.gc, 12, -5]].forEach(([gs, dx, dy]) => gs.forEach((g) => {
        ft(g, { opacity: 0.9, x: dx, y: dy }, { opacity: 0, x: 0, y: 0, duration: 0.2, ease: 'steps(5)' }, x);
      }));
      ft(L.p, { x: -18 }, { x: 0, duration: 0.16, ease: 'steps(4)' }, x);
      ft(L.p, { clipPath: 'inset(0% 0% 48% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.1, ease: 'steps(2)' }, x + 0.03);
      if (k < 2) {
        tl.to(L.p, { y: PORTRAIT ? -lh * 0.95 : -lh * 1.05, scale: PORTRAIT ? 0.5 : 0.62, opacity: 0.34, filter: 'blur(1.5px)', duration: 0.18, ease: 'power3.out' }, x + 0.04);
        // the line that was already pushed up moves up again
        if (k === 1) tl.to(lines[0].p, { y: PORTRAIT ? -lh * 1.55 : -lh * 1.75, scale: PORTRAIT ? 0.4 : 0.5, opacity: 0.22, duration: 0.18, ease: 'power3.out' }, x + 0.04);
      }
    });
    // the nods animate while they are up
    dlgs.forEach((d, i) => ft(d, { scale: 0.7, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.18, ease: 'back.out(2.4)' }, lines[0].c.t0 + i * 0.16));
    chipsL.forEach((c, i) => ft(c, { y: 30, opacity: 0 }, { y: 0, opacity: 1, duration: 0.2, ease: 'back.out(2)' }, lines[1].c.t0 + i * 0.12));
    verL.forEach((c, i) => ft(c, { y: 30, opacity: 0 }, { y: 0, opacity: 1, duration: 0.2, ease: 'back.out(2)' }, lines[2].c.t0 + i * 0.12));
    // the music cuts on the last strike: everything drops to near-black
    tl.to(lines.map((l) => l.p), { opacity: 0, filter: 'blur(10px)', duration: 0.14, ease: 'power2.in' }, S('x3') + 0.08);
    doFlash(S('x3'), 0.5);
  }

  // ── 1b. The turn: "What if your dev stack… just worked?" (light-speed into the slam) ──
  if (has('h4e')) {
    const R = scene('turn-s', S('x3'), S('slam') + 0.25, false);
    const c = card('H4');
    const t = el('div', 'turn', R); t.style.fontSize = A.turn + 'px';
    t.style.top = (PORTRAIT ? 830 : 440) + 'px';
    if (PORTRAIT) { t.style.left = '70px'; t.style.right = '70px'; t.style.whiteSpace = 'normal'; }
    const ws = tokens(t, c.toks);
    ws[ws.length - 1].classList.add('k');
    c.toks.forEach((tk, i) => ft(ws[i], { opacity: 0, y: 26, filter: 'blur(10px)' }, { opacity: 1, y: 0, filter: 'blur(0px)', duration: 0.32, ease: EXPO }, tk.t));
    ft(t, { scale: 0.96 }, { scale: 1.05, duration: S('slam') - S('x3'), ease: 'power1.in' }, S('x3'));
    tl.to(t, { scale: 2.6, opacity: 0, filter: 'blur(18px)', duration: 0.2, ease: 'power3.in' }, S('slam') - 0.04);
    tl.to('#trails', { opacity: 0.12, duration: 0.2 }, S('x3'));
  }

  // ── 2. Logo slam on the drop ──────────────────────────────────────────────────
  const LOGO = $('#logo-tpl').innerHTML;
  {
    const [t0] = [S('slam')];
    const t1 = has('stack') ? words('L04').find((w) => w.i === 4).t + 0.1 : S('pickin');
    const R = scene('logo-s', t0 - 0.05, t1, false);
    el('div', 'flare', R).id = 'flare3';
    el('div', 'streak', R).id = 'streak3';
    const sh = el('div', 'shock', R);
    const lk = el('div', 'lockup', R, LOGO);
    lk.style.top = (PORTRAIT ? 880 : 450) + 'px';
    if (PORTRAIT) { $('#streak3').style.top = '950px'; }
    ft(lk, { scale: 2.8, opacity: 0, filter: 'blur(20px)' }, { scale: 1, opacity: 1, filter: 'blur(0px)', duration: 0.17, ease: 'power4.out' }, t0 - 0.06);
    ft(lk, { scale: 1 }, { scale: 1.06, duration: (has('stack') ? S('stack') : S('pickin')) - t0, ease: 'none' }, t0 + 0.12);
    ft('#flare3', { opacity: 0, scale: 0.4 }, { opacity: 1, scale: 1, duration: 0.14, ease: 'power2.out' }, t0);
    tl.to('#flare3', { opacity: 0.18, scale: 1.7, duration: 1.4, ease: 'power2.out' }, t0 + 0.14);
    ft('#streak3', { opacity: 0, scaleX: 0.05 }, { opacity: 1, scaleX: 1, duration: 0.25, ease: 'power3.out' }, t0);
    tl.to('#streak3', { opacity: 0, duration: 0.8, ease: 'power2.in' }, t0 + 0.25);
    ft(sh, { opacity: 1, scale: 0.2 }, { opacity: 0, scale: PORTRAIT ? 5 : 6, duration: 0.7, ease: 'power2.out' }, t0);
    doFlash(t0, 0.95); shake(t0, 26, 8);
    if (has('stack')) {
      // "Your whole local stack." — the logo lifts, the stack chips pop on the beat
      tl.to(lk, { y: PORTRAIT ? -420 : -250, scale: 0.62, duration: 0.45, ease: IO }, S('stack') - 0.35);
      const row = el('div', 'chiprow', R); row.style.top = (PORTRAIT ? 860 : 450) + 'px';
      if (PORTRAIT) { row.style.left = '80px'; row.style.right = '80px'; }
      const names = ['nginx', 'Apache', 'PHP 8.5', 'Node.js', 'MySQL', 'PostgreSQL', 'Redis', 'Mailpit', 'https://*.test'];
      names.forEach((nm, i) => {
        const c = el('span', 'chip' + (i === names.length - 1 ? ' on' : ''), row, (i === names.length - 1 ? '<i></i>' : '') + nm);
        ft(c, { y: 40, opacity: 0, scale: 0.8 }, { y: 0, opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2.2)' }, S('stack') + i * 0.5 * BEAT);
      });
      const one = words('L04').find((w) => w.i === 4);
      tl.to([row, lk], { scale: 0.7, opacity: 0, filter: 'blur(14px)', duration: 0.3, ease: 'power3.in' }, one.t - 0.25);
    } else {
      tl.to(lk, { scale: 0.8, opacity: 0, filter: 'blur(16px)', duration: 0.3, ease: 'power3.in' }, S('pickin') - 0.3);
    }
  }
  // "One app." — the real dashboard flies in from depth
  if (has('stack')) {
    const one = words('L04').find((w) => w.i === 4);
    const R = scene('oneapp', one.t - 0.1, S('pickin'));
    const crop = [236, 40, 1204, 760];
    const P = shotPanel(R, 'dashboard', crop, geo(crop, A.pw, A.ph));
    ft(P.el, { opacity: 0, z: -1400, rotationX: 28, y: 160, filter: 'blur(20px)' }, { opacity: 1, z: 0, rotationX: 6, y: 0, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, one.t - 0.08);
    tl.to(P.el, { rotationX: 0, duration: 1.2, ease: SINE }, one.t + 0.4);
    camTo(P, { at: one.t + 0.3, dur: S('pickin') - one.t, ease: SINE, cx: 720, cy: 300, cw: 1000 });
    sweep($('.sheen', P.el), one.t + 0.05, 0.7);
    doFlash(one.t, 0.35, true);
    tl.to(P.el, { opacity: 0, x: -300, filter: 'blur(16px)', duration: 0.28, ease: 'power3.in' }, S('pickin') - 0.27);
  }

  // ── 3. Onboarding: pick a project (click on the beat) … and it's live ──────────
  {
    const t0 = S('pickin'), tl1 = S('live');
    const R = scene('onb', t0 - 0.05, tl1 + 0.05);
    const crop = PORTRAIT ? [430, 360, 760, 600] : [0, 0, 1440, 900];
    const g = geo(crop, A.pw, A.ph);
    const p = el('div', 'panel', R); const c = el('div', 'cnt', p);
    const i1 = el('img', 'shot', c); i1.src = SHOT('onboarding-first-site');
    const i2 = el('img', 'shot', c); i2.src = SHOT('onboarding-creating');
    const clk = el('div', 'click', c);
    const cur = el('div', '', c, '<svg class="cursor" style="opacity:1" viewBox="0 0 24 24"><path d="M4 2.5 L4 19.5 L8.6 15.4 L11.6 21.8 L14.4 20.5 L11.4 14.2 L17.6 14.2 Z" fill="#fff" stroke="#06090d" stroke-width="1.4" stroke-linejoin="round" /></svg>');
    cur.style.position = 'absolute'; cur.style.left = '0'; cur.style.top = '0';
    el('div', 'sheen', p);
    const P = panel(p, { crop, w: g.w, left: g.left, top: g.top }); P.el = p;
    gsap.set(i2, { opacity: 0 });
    ft(p, { opacity: 0, z: -900, rotationX: 26, rotationY: -12, y: 160, filter: 'blur(18px)' }, { opacity: 1, z: 0, rotationX: 4, rotationY: -2, y: 0, filter: 'blur(0px)', duration: 0.55, ease: EXPO }, t0);
    tl.to(p, { rotationX: 0, rotationY: 0, duration: 1.4, ease: SINE }, t0 + 0.5);
    sweep($('.sheen', p), t0 + 0.2, 0.8);
    const ck = S('click');
    gsap.set(cur, { x: 520, y: 420, scale: PORTRAIT ? 1.8 : 1.4, transformOrigin: '4px 3px' });
    tl.to(cur, { x: 920, y: 778, duration: Math.max(0.5, ck - t0 - 0.55), ease: 'power3.inOut' }, t0 + 0.4);
    tl.to(cur, { scale: PORTRAIT ? 1.45 : 1.15, duration: 0.06, yoyo: true, repeat: 1 }, ck - 0.05);
    gsap.set(clk, { left: 925, top: 787 });
    ft(clk, { opacity: 0.95, scale: 0.3 }, { opacity: 0, scale: 1.8, duration: 0.5, ease: 'power2.out' }, ck);
    tl.set(i2, { opacity: 1 }, ck + 0.08);
    tl.set(cur, { opacity: 0 }, ck + 0.1);
    doFlash(ck, 0.25);
    camTo(P, { at: ck + 0.05, dur: tl1 - ck - 0.05, ease: 'power2.in', cx: 720, cy: 395, cw: PORTRAIT ? 520 : 760 });
    tl.to(p, { z: 160, duration: tl1 - ck, ease: 'power2.in' }, ck);
  }
  // success: "Your site is live" + https://hello.test (and, on 16:9, the three punches)
  {
    const t0 = S('live');
    const t1 = has('https') ? S('sites') : S('svc');
    const R = scene('live-s', t0 - 0.02, t1);
    const crop = PORTRAIT ? [440, 230, 560, 540] : [0, 0, 1440, 900];
    const g = geo(crop, A.pw, A.ph);
    const P = shotPanel(R, 'onboarding-success', crop, { ...g, view: PORTRAIT ? undefined : [720, 380, 1100] });
    const rg = el('div', 'ring', P.c); ring(rg, [612, 378, 216, 34], t0 + 0.12);
    ft(P.el, { opacity: 0, scale: 1.2, filter: 'blur(24px)' }, { opacity: 1, scale: 1, filter: 'blur(0px)', duration: 0.4, ease: EXPO }, t0 - 0.02);
    doFlash(t0, 0.7, true); shake(t0, 12, 4);
    sweep($('.sheen', P.el), t0, 0.8);
    if (has('https')) {
      const L7 = words('L07');
      const at = (i) => L7.find((w) => w.i === i).t;
      camTo(P, { at: t0 + 0.4, dur: at(0) - t0 - 0.4, ease: SINE, cx: 720, cy: 370, cw: 900 });
      camTo(P, { at: at(0) - 0.04, dur: 0.16, ease: 'expo.out', cx: 720, cy: 395, cw: 430 });
      camTo(P, { at: at(0) + 0.2, dur: at(2) - at(0) - 0.25, ease: 'none', cx: 715, cy: 395, cw: 400 });
      camTo(P, { at: at(2) - 0.04, dur: 0.16, ease: 'expo.out', cx: 775, cy: 395, cw: 250 });
      camTo(P, { at: at(2) + 0.2, dur: at(4) - at(2) - 0.25, ease: 'none', cx: 780, cy: 395, cw: 236 });
      camTo(P, { at: at(4) - 0.04, dur: 0.22, ease: 'expo.out', cx: 720, cy: 450, cw: 1440 });
      doFlash(at(0), 0.25); doFlash(at(2), 0.25); doFlash(at(4), 0.5, true); shake(at(4), 14, 4);
      tl.to(P.el, { rotationY: -6, rotationX: 4, duration: S('sites') - at(4), ease: SINE }, at(4));
    } else {
      camTo(P, { at: t0 + 0.3, dur: t1 - t0 - 0.3, ease: SINE, cx: 720, cy: 390, cw: PORTRAIT ? 420 : 800 });
    }
    tl.to(P.el, { opacity: 0, x: -320, filter: 'blur(18px)', duration: 0.26, ease: 'power3.in' }, t1 - 0.25);
  }

  // ── 4. Sites: every project gets its own .test ────────────────────────────────
  if (has('sites')) {
    const [t0, t1] = [S('sites'), S('svc')];
    const R = scene('sites-s', t0 - 0.12, t1);
    const crop = PORTRAIT ? [270, 160, 760, 640] : [236, 140, 1204, 640];
    const P = shotPanel(R, 'sites', crop, geo(crop, A.pw, A.ph));
    ft(P.el, { opacity: 0, x: 520, z: -500, rotationY: 40, rotationX: 8, filter: 'blur(18px)' }, { opacity: 1, x: 0, z: 0, rotationY: 12, rotationX: 4, filter: 'blur(0px)', duration: 0.55, ease: EXPO }, t0 - 0.12);
    tl.to(P.el, { rotationY: 4, rotationX: 2, duration: t1 - t0, ease: SINE }, t0 + 0.4);
    camTo(P, { at: t0 + 0.3, dur: t1 - t0 - 0.3, ease: SINE, cx: 760, cy: 330, cw: PORTRAIT ? 560 : 1000 });
    sweep($('.sheen', P.el), t0, 0.8);
    const rects = [[345, 196, 82, 24], [727, 196, 66, 24], [1111, 196, 75, 24], [345, 390, 80, 24], [727, 390, 130, 24], [1111, 390, 106, 24]];
    rects.forEach((r, i) => { const rg = el('div', 'ring', P.c); ring(rg, [r[0] - 6, r[1] - 4, r[2] + 12, r[3] + 8], t0 + 0.35 + i * BEAT * 0.75); });
    tl.to(P.el, { opacity: 0, x: -300, filter: 'blur(16px)', duration: 0.24, ease: 'power3.in' }, t1 - 0.23);
  }

  // ── 5. Services staccato: one word = one hard cut + chip pop ───────────────────
  {
    const ws = words('L09');
    const t1 = has('run') ? S('run') : (has('ai') ? S('ai') : S('free') - 1.2 * BEAT);
    const shots = {
      0: ['services', [820, 300, 310, 150], 'PHP'], 1: ['services', [1112, 568, 310, 150], 'Node.js'], 2: ['dashboard', [290, 672, 780, 52], 'MySQL'],
      3: ['services', [530, 434, 310, 150], 'PostgreSQL'], 4: ['services', [1112, 434, 310, 150], 'Redis'],
    };
    ws.forEach((w, k) => {
      const nx = ws[k + 1] ? ws[k + 1].t : t1;
      const R = scene('svc-' + k, w.t - 0.001, nx);
      const [img, r, label] = shots[w.i];
      const cw = PORTRAIT ? 560 : 820, chh = PORTRAIT ? 560 : 460;
      const cx = r[0] + Math.min(r[2], 400) / 2, cyy = r[1] + r[3] / 2;
      const crop = [Math.max(0, Math.min(1440 - cw, cx - cw / 2)), Math.max(0, Math.min(900 - chh, cyy - chh / 2)), cw, chh];
      const P = shotPanel(R, img, crop, geo(crop, A.pw, PORTRAIT ? 860 : 700, PORTRAIT ? 760 : 420));
      gsap.set(P.el, { opacity: 1 });
      const rg = el('div', 'ring', P.c); ring(rg, r, w.t + 0.03);
      const dir = k % 2 ? 1 : -1;
      ft(P.el, { scale: 1.12, rotationZ: dir * 1.2 }, { scale: 1, rotationZ: 0, duration: 0.35, ease: EXPO }, w.t);
      const ch = el('div', 'tagchip', R, `<i></i>${label}`);
      ch.style.fontSize = (PORTRAIT ? 84 : 76) + 'px';
      gsap.set(ch, PORTRAIT ? { left: 0, right: 0, margin: '0 auto', width: 'max-content', top: 1240 } : { left: 0, right: 0, margin: '0 auto', width: 'max-content', top: 800 });
      ft(ch, { opacity: 0, scale: 1.5, y: 20 }, { opacity: 1, scale: 1, y: 0, duration: 0.16, ease: 'back.out(2.5)' }, w.t);
      doFlash(w.t, 0.22);
    });
  }
  if (has('run')) {
    const [t0, t1] = [S('run'), S('ai')];
    const R = scene('run-s', t0 - 0.05, t1);
    const crop = [236, 100, 1204, 540];
    const P = shotPanel(R, 'dashboard', crop, geo(crop, A.pw, A.ph));
    ft(P.el, { opacity: 0, scale: 1.25, filter: 'blur(16px)' }, { opacity: 1, scale: 1, filter: 'blur(0px)', duration: 0.35, ease: EXPO }, t0 - 0.05);
    const rg = el('div', 'ring', P.c); ring(rg, [300, 145, 210, 34], t0 + 0.1);
    const rg2 = el('div', 'ring', P.c); ring(rg2, [1135, 148, 120, 26], t0 + 0.3);
    camTo(P, { at: t0 + 0.2, dur: t1 - t0 - 0.2, ease: SINE, cx: 720, cy: 280, cw: 1000 });
    doFlash(t0, 0.4, true);
  }

  // ── 6. AI: something breaks? just ask your AI (real MCP tool calls) ────────────
  if (has('ai')) {
    const t0 = S('ai'), ta = S('ask'), t1 = has('mont') ? S('mont') : S('bd');
    const R = scene('ai-s', t0 - 0.03, t1);
    const crop = [236, 600, 1204, 300];
    const bcrop = PORTRAIT ? [281, 520, 760, 380] : [236, 470, 1204, 430];
    const bgP = shotPanel(R, 'dashboard', bcrop, geo(bcrop, A.pw, A.ph));
    gsap.set(bgP.el, { opacity: 1 });
    ft(bgP.el, { scale: 1.1, filter: 'blur(0px)' }, { scale: 1, duration: 0.3, ease: EXPO }, t0);
    const rr = el('div', 'ring red', bgP.c); ring(rr, [290, 778, 780, 50], t0 + 0.05);
    const toast = el('div', 'toast', R, '<i></i>Redis stopped <span>shop · queue failing</span>');
    gsap.set(toast, PORTRAIT ? { left: 0, right: 0, margin: '0 auto', width: 'max-content', top: 1200 } : { left: 0, right: 0, margin: '0 auto', width: 'max-content', top: 760 });
    ft(toast, { opacity: 0, y: 30, scale: 0.9 }, { opacity: 1, y: 0, scale: 1, duration: 0.25, ease: 'back.out(2)' }, t0 + 0.08);
    doFlash(t0, 0.3); shake(t0, 14, 5);
    // glitch on the dashboard
    ft(bgP.el, { x: -14 }, { x: 0, duration: 0.18, ease: 'steps(4)' }, t0);
    tl.to(toast, { opacity: 0, y: -20, duration: 0.2 }, ta - 0.15);
    tl.to(bgP.el, { opacity: 0.35, filter: 'blur(4px)', scale: 0.94, duration: 0.35, ease: IO }, ta - 0.2);
    const chat = $('#chat-tpl').content.firstElementChild.cloneNode(true);
    R.appendChild(chat);
    if (PORTRAIT) gsap.set(chat, { left: 40, right: 40, width: 'auto', top: 520 });
    else gsap.set(chat, { left: (W - 980) / 2, right: 'auto', width: 980, top: 120 });
    ft(chat, { opacity: 0, y: 90, z: -300, rotationX: 14, filter: 'blur(14px)' }, { opacity: 1, y: 0, z: 0, rotationX: 0, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, ta - 0.1);
    const u = $('.msg-user', chat);
    ft(u, { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.25, ease: 'power2.out' }, ta + 0.1);
    [...u.querySelectorAll('.w')].forEach((w, i) => ft(w, { opacity: 0 }, { opacity: 1, duration: 0.05, ease: 'none' }, ta + 0.1 + i * 0.055));
    const a = S('ask', 2.5);
    const step = (sel, s0, d0) => {
      const e = $(sel, chat);
      ft(e, { opacity: 0, y: 14, filter: 'blur(6px)' }, { opacity: 1, y: 0, filter: 'blur(0px)', duration: 0.3, ease: EXPO }, s0);
      ft($('.spin', e), { rotation: 0 }, { rotation: 540, duration: d0 - s0, ease: 'none' }, s0);
      tl.to($('.spin', e), { opacity: 0, duration: 0.08 }, d0 - 0.04);
      ft($('.ok', e), { opacity: 0, scale: 0.4 }, { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(3)' }, d0);
      ft($('.res', e), { opacity: 0, x: -8 }, { opacity: 1, x: 0, duration: 0.25, ease: 'power2.out' }, d0 + 0.04);
    };
    step('.t1', a, a + BEAT);
    step('.t2', a + 1.5 * BEAT, a + 2.5 * BEAT);
    step('.t3', a + 3 * BEAT, a + 4 * BEAT);
    ft($('.msg-ai', chat), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.4, ease: EXPO }, Math.min(a + 4.5 * BEAT, t1 - 0.5));
    tl.to(chat, { scale: 1.03, duration: t1 - ta, ease: 'none' }, ta + 0.4);
    tl.to([chat, bgP.el], { opacity: 0, z: -400, filter: 'blur(20px)', duration: 0.26, ease: 'power3.in' }, t1 - 0.25);
  }

  // ── 7. Montage: Cron. Logs. Git. Databases. — one cut per word, punch on the off-beat ──
  if (has('mont')) {
    const ws = words('L13');
    const t1 = has('here') ? S('here') : S('bd');
    const shots = [['cron', [236, 40, 1204, 440], 'Cron'], ['logs', [236, 40, 1204, 760], 'Logs'], ['site-detail', [281, 160, 1123, 290], 'Git'], ['databases', [236, 92, 1204, 580], 'Databases']];
    const gitRing = [584, 218, 76, 30];
    ws.forEach((w, k) => {
      const nx = ws[k + 1] ? ws[k + 1].t : t1;
      const R = scene('mont-' + k, w.t - 0.001, nx);
      const [img, crop0, label] = shots[w.i];
      const crop = PORTRAIT ? [crop0[0], crop0[1], Math.min(crop0[2], 760), Math.min(crop0[3], 640)] : crop0;
      const P = shotPanel(R, img, crop, geo(crop, PORTRAIT ? A.pw : 1180, PORTRAIT ? 760 : 700, PORTRAIT ? 700 : 450));
      gsap.set(P.el, { opacity: 1 });
      const dir = k % 2 ? 1 : -1;
      ft(P.el, { x: 140 * dir, rotationY: -18 * dir, scale: 1.08 }, { x: 0, rotationY: -4 * dir, scale: 1, duration: 0.3, ease: EXPO }, w.t);
      // the off-beat punch-in keeps the picture changing every beat
      const mid = (w.t + nx) / 2;
      const cx = img === 'site-detail' ? 620 : crop[0] + crop[2] / 2, cy = img === 'site-detail' ? 232 : crop[1] + crop[3] * 0.4;
      camTo(P, { at: mid - 0.02, dur: 0.14, ease: 'expo.out', cx, cy, cw: crop[2] * 0.62 });
      if (img === 'site-detail') { const rg = el('div', 'ring', P.c); ring(rg, gitRing, w.t + 0.1); }
      const big = el('div', 'big', R, label);
      big.style.fontSize = (PORTRAIT ? 150 : 150) + 'px';
      gsap.set(big, PORTRAIT ? { left: 0, right: 0, textAlign: 'center', top: 1160 } : { left: 0, right: 0, textAlign: 'center', top: 830 });
      ft(big, { opacity: 0, scale: 1.4, filter: 'blur(10px)' }, { opacity: 1, scale: 1, filter: 'blur(0px)', duration: 0.16, ease: 'power4.out' }, w.t);
      doFlash(w.t, 0.2);
    });
  }
  if (has('here')) {
    const [t0, t1] = [S('here'), S('bd')];
    const R = scene('here-s', t0 - 0.02, t1);
    const imgs = ['dashboard', 'sites', 'services', 'databases', 'logs', 'cron', 'site-detail', 'tools', 'ai'];
    const cols = 3, gw = 560, gh = 350, gx = 40, gy = 34;
    const x0 = (W - (cols * gw + (cols - 1) * gx)) / 2, y0 = (H - (3 * gh + 2 * gy)) / 2 - 20;
    imgs.forEach((n, i) => {
      const t = el('div', 'tile', R); const im = el('img', '', t); im.src = SHOT(n);
      gsap.set(t, { left: x0 + (i % cols) * (gw + gx), top: y0 + Math.floor(i / cols) * (gh + gy), width: gw, height: gh });
      ft(t, { opacity: 0, scale: 0.7, z: -300 }, { opacity: 1, scale: 1, z: 0, duration: 0.28, ease: 'back.out(1.6)' }, t0 + ((i * 5) % 9) * 0.045);
    });
    const wall = R;
    ft(wall, { scale: 1.6 }, { scale: 1.0, duration: t1 - t0, ease: 'power2.out' }, t0);
    doFlash(t0, 0.35, true);
  }

  // ── 8. "And the best part?" — everything drops out ────────────────────────────
  {
    const t0 = S('bd'), t1 = S('free');
    const R = scene('bd-s', t0, t1 + 0.05, false);
    ft(black, { opacity: 0 }, { opacity: 0.9, duration: 0.25, ease: 'power2.in' }, t0);
    tl.to(black, { opacity: 0, duration: 0.12 }, t1 - 0.02);
    tl.to('#trails', { opacity: 0.06, duration: 0.3 }, t0);
    tl.to('#floor', { opacity: 0.1, duration: 0.3 }, t0);
    const c = card('L15');
    if (c) {
      const q = el('div', 'bestq', R); q.style.fontSize = (PORTRAIT ? 92 : 84) + 'px'; q.style.top = (PORTRAIT ? 880 : 470) + 'px';
      const ws = tokens(q, c.toks);
      c.toks.forEach((tk, i) => ft(ws[i], { opacity: 0, y: 20, filter: 'blur(8px)' }, { opacity: 1, y: 0, filter: 'blur(0px)', duration: 0.3, ease: EXPO }, tk.t));
      ft(q, { scale: 1 }, { scale: 1.06, duration: t1 - t0, ease: 'none' }, t0);
      tl.to(q, { opacity: 0, scale: 0.9, duration: 0.12 }, Math.min(t1, card('L16').t0) - 0.14);
    }
  }

  // ── 9. "It's free." — the final hit ───────────────────────────────────────────
  {
    const t0 = S('free'), t1 = S('card');
    const R = scene('free-s', t0 - 0.4, t1 + 0.05, false);
    el('div', 'flare', R).id = 'flare4';
    const sh = el('div', 'shock', R);
    const c = card('L16');
    const f = el('div', 'freebig', R); f.style.fontSize = A.free + 'px'; f.style.top = ((PORTRAIT ? 960 : 540) - A.free * 0.55) + 'px';
    const ws = tokens(f, c.toks);
    ws[ws.length - 1].classList.add('k');
    c.toks.forEach((tk, i) => ft(ws[i], { opacity: 0, scale: i ? 2.2 : 1.4, filter: 'blur(16px)' }, { opacity: 1, scale: 1, filter: 'blur(0px)', duration: i ? 0.16 : 0.2, ease: 'power4.out' }, tk.t - (i ? 0.03 : 0)));
    ft(f, { scale: 1 }, { scale: 1.08, duration: t1 - t0, ease: 'none' }, t0);
    ft('#flare4', { opacity: 0, scale: 0.4 }, { opacity: 1, scale: 1.1, duration: 0.14, ease: 'power2.out' }, t0);
    tl.to('#flare4', { opacity: 0.3, scale: 1.8, duration: 1.4, ease: 'power2.out' }, t0 + 0.14);
    ft(sh, { opacity: 1, scale: 0.2 }, { opacity: 0, scale: 6, duration: 0.8, ease: 'power2.out' }, t0);
    doFlash(t0, 0.6); shake(t0, 30, 9);
    tl.to('#trails', { opacity: 0.9, duration: 0.15 }, t0);
    tl.to('#trails', { opacity: 0.45, duration: 1.4, ease: SINE }, t0 + 0.3);
    tl.to(f, { scale: 0.6, opacity: 0, filter: 'blur(16px)', y: PORTRAIT ? -300 : -200, duration: 0.3, ease: 'power3.in' }, t1 - 0.28);
  }

  // ── 10. End card ──────────────────────────────────────────────────────────────
  {
    const t0 = S('card'), t1 = LEN;
    const R = scene('end-s', t0 - 0.05, t1 + 1, false);
    el('div', 'flare', R).id = 'flare5';
    const ec = el('div', 'endcard', R);
    const lk = el('div', 'lockup sm', ec, LOGO);
    const tag = el('p', 'tag', ec, 'Your whole local stack. One app.');
    const cta = el('div', 'ctarow', ec, '<span class="free">Free for Windows &amp; macOS</span><span class="btn" id="end-btn">Download<span class="btn-sheen" id="btn-sheen3"></span></span>');
    const url = el('div', 'endurl', ec, 'envkit.net');
    if (PORTRAIT) { lk.style.top = '560px'; tag.style.top = '760px'; cta.style.top = '900px'; url.style.top = '1210px'; url.style.fontSize = '64px'; }
    else { lk.style.top = '250px'; tag.style.top = '450px'; cta.style.top = '570px'; url.style.top = '720px'; url.style.fontSize = '54px'; }
    const bars = [...lk.querySelectorAll('.bar')];
    ft(bars, { x: -90, opacity: 0, filter: 'blur(8px)' }, { x: 0, opacity: 1, filter: 'blur(0px)', duration: 0.35, ease: 'power4.out', stagger: 0.05 }, t0 - 0.2);
    ft($('.k', lk), { x: 80, y: -40, opacity: 0 }, { x: 0, y: 0, opacity: 1, duration: 0.3, ease: 'power4.out' }, t0 - 0.12);
    ft($('.word', lk), { x: -30, opacity: 0, filter: 'blur(12px)' }, { x: 0, opacity: 1, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, t0 + 0.05);
    ft('#flare5', { opacity: 0, scale: 0.4 }, { opacity: 0.7, scale: 1, duration: 0.2, ease: 'power2.out' }, t0);
    tl.to('#flare5', { opacity: 0.18, scale: 1.5, duration: 2, ease: 'power2.out' }, t0 + 0.2);
    ft(tag, { y: 26, opacity: 0, filter: 'blur(10px)' }, { y: 0, opacity: 1, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, t0 + 2 * BEAT);
    const env = words('L17');
    const forW = env.find((w) => w.i === 1) || env[0];
    ft(cta, { y: 26, opacity: 0, filter: 'blur(10px)' }, { y: 0, opacity: 1, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, forW.t - 0.05);
    ft(url, { y: 20, opacity: 0, filter: 'blur(8px)' }, { y: 0, opacity: 1, filter: 'blur(0px)', duration: 0.5, ease: EXPO }, forW.t + 3 * BEAT);
    ft('#btn-sheen3', { xPercent: -160 }, { xPercent: 360, duration: 0.8, ease: 'power2.inOut' }, forW.t + 4 * BEAT);
    ft('#btn-sheen3', { xPercent: -160 }, { xPercent: 360, duration: 0.8, ease: 'power2.inOut' }, Math.max(forW.t + 4 * BEAT + 1, LEN - 1.1));
    ft(ec, { scale: 0.985 }, { scale: 1.02, duration: LEN - t0, ease: 'none' }, t0);
    tl.to('#floor', { opacity: 0.45, duration: 0.6 }, t0);
    tl.to('#trails', { opacity: 0.55, duration: 0.6 }, t0);
    doFlash(t0, 0.5, true);
  }

  // ── Captions: word-by-word, current word in mint (hero lines are the big type itself) ──
  {
    const CAP = $('#caps');
    const scrim = el('div', 'scrim', CAP);
    if (PORTRAIT) scrim.style.display = 'none';
    const cards = T.cards.filter((c) => !c.hero);
    cards.forEach((c, k) => {
      const ln = el('div', 'capline', CAP);
      ln.style.fontSize = A.cap + 'px';
      ln.style.top = (A.capY - A.cap * 0.6) + 'px';
      if (PORTRAIT) { ln.style.whiteSpace = 'normal'; ln.style.left = '70px'; ln.style.right = '70px'; ln.style.lineHeight = '1.12'; ln.style.fontWeight = 780; }
      const ws = tokens(ln, c.toks);
      const next = cards[k + 1];
      const tOut = Math.min(c.t1 + 0.45, next ? next.t0 - 0.2 : LEN);
      // the whole line is on screen (dim) so it stays centred and readable; the spoken word lights up mint
      gsap.set(ws, { opacity: 0.38 });
      ft(ln, { opacity: 0, y: PORTRAIT ? 18 : 10 }, { opacity: 1, y: 0, duration: 0.14, ease: 'power2.out' }, c.t0 - 0.16);
      c.toks.forEach((tk, i) => {
        ft(ws[i], { opacity: 0.38, scale: 1.0 }, { opacity: 1, scale: 1.06, duration: 0.07, ease: 'power2.out' }, tk.t);
        tl.to(ws[i], { scale: 1, duration: 0.18, ease: 'power2.out' }, tk.t + 0.07);
        tl.set(ws[i], { color: '#2dd4aa' }, tk.t);
        tl.set(ws[i], { color: '#f4f8fb' }, i + 1 < c.toks.length ? c.toks[i + 1].t : tOut);
      });
      tl.to(ln, { opacity: 0, duration: 0.1 }, tOut - 0.1);
      if (!PORTRAIT) { tl.to(scrim, { opacity: 1, duration: 0.15 }, c.t0 - 0.12); tl.to(scrim, { opacity: 0, duration: 0.2 }, tOut); }
    });
  }

  tl.set({}, {}, LEN);
  window.__timelines = window.__timelines || {};
  window.__timelines[ROOT.dataset.compositionId] = tl;
  tl.seek(0);
})();
